
.qj-inventory {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.qj-card {
  position: relative;
  background: linear-gradient(180deg, var(--qj-black-panel), rgba(17, 20, 24, 0.55));
  border: 1px solid var(--qj-moon-dim);
  box-shadow:
    inset 0 0 22px rgba(0, 0, 0, 0.5),
    0 0 0 1px rgba(0, 0, 0, 0.6);
  padding: 14px 16px;
}

.qj-card::before {
  content: '';
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(122, 140, 153, 0.18);
  pointer-events: none;
}

.qj-card__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
  padding-bottom: 7px;
  border-bottom: 1px dashed var(--qj-moon-dim);
}

.qj-card__title {
  font-family: var(--qj-font-display);
  font-size: 15px;
  letter-spacing: 5px;
  color: var(--qj-moon);
}

.qj-card__value {
  font-family: var(--qj-font-data);
  font-variant-numeric: tabular-nums;
  font-size: 15px;
  color: var(--qj-moon-bright);
}
.qj-card__value i {
  font-family: var(--qj-font-display);
  font-style: normal;
  font-size: 11px;
  color: var(--qj-text-dim);
  margin-left: 2px;
}

/* 货币 */
.qj-coin {
  display: flex;
  gap: 10px;
}

.qj-coin__item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 10px 4px;
  border: 1px solid var(--qj-moon-dim);
  background: rgba(0, 0, 0, 0.35);
}

.qj-coin__value {
  font-family: var(--qj-font-data);
  font-variant-numeric: tabular-nums;
  font-size: 19px;
}

.qj-coin__label {
  font-size: 11px;
  letter-spacing: 2px;
  color: var(--qj-text-dim);
}

/* 装备栏 */
.qj-equip {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.qj-equip__slot {
  font-size: 12px;
  letter-spacing: 2px;
  color: var(--qj-text-dim);
  flex-shrink: 0;
}

.qj-equip__value {
  font-family: var(--qj-font-display);
  font-size: 16px;
  color: var(--qj-moon-bright);
  letter-spacing: 1px;
}

/* 物品 · 平铺 */
.qj-item__list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.qj-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 10px;
  border: 1px solid rgba(122, 140, 153, 0.22);
  background: rgba(0, 0, 0, 0.3);
  transition:
    border-color 0.2s,
    background 0.2s;
}

.qj-item:hover {
  border-color: var(--qj-moon-dim);
  background: rgba(122, 140, 153, 0.06);
}

.qj-item__detail {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.qj-item__name {
  font-size: 13px;
  color: var(--qj-text);
  letter-spacing: 1px;
}

.qj-item__desc {
  font-size: 11px;
  color: var(--qj-text-dim);
  line-height: 1.4;
}

.qj-item__count {
  flex-shrink: 0;
  font-family: var(--qj-font-data);
  font-variant-numeric: tabular-nums;
  font-size: 13px;
  color: var(--qj-moon-bright);
}

/* 悬停浮现的分类角标 */
.qj-item__tag {
  position: absolute;
  right: 8px;
  bottom: 6px;
  font-size: 10px;
  letter-spacing: 1px;
  color: var(--qj-moon-bright);
  border: 1px solid var(--qj-moon-dim);
  background: var(--qj-black);
  padding: 0 6px;
  opacity: 0;
  transform: translateY(4px);
  transition:
    opacity 0.2s,
    transform 0.2s;
  pointer-events: none;
}

.qj-item:hover .qj-item__tag {
  opacity: 1;
  transform: translateY(0);
}

.qj-item__empty {
  font-size: 12px;
  letter-spacing: 2px;
  color: var(--qj-text-dim);
  opacity: 0.7;
  padding: 8px 0;
}

@media (max-width: 480px) {
  .qj-coin {
    flex-direction: column;
  }
}
